From 0899f8ba4e8f7b4db9a0083bbce5e7e79867881d Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 02:52:22 +0100
Subject: [PATCH] kioworkers/desktop: refresh desktop items when a file is
 rewritten in place

The desktop notifier only watched the Desktop folder for entries being
added or removed, so a file overwritten in place kept its old thumbnail,
size and date until F5. Also watch the files and send FilesChanged.

BUG: 501016
BUG: 523799
---
 kioworkers/desktop/desktopnotifier.cpp | 23 +++++++++++++++++++++++
 kioworkers/desktop/desktopnotifier.h   |  3 +++
 2 files changed, 26 insertions(+)

diff --git a/kioworkers/desktop/desktopnotifier.cpp b/kioworkers/desktop/desktopnotifier.cpp
index b76be9ef51..6b8dfe12e0 100644
--- a/kioworkers/desktop/desktopnotifier.cpp
+++ b/kioworkers/desktop/desktopnotifier.cpp
@@ -7,12 +7,14 @@
 #include "desktopnotifier.h"

 #include <KDesktopFile>
+#include <KDirWatch>
 #include <KPluginFactory>

 #include <kdirnotify.h>

 #include <QDir>
 #include <QFile>
+#include <QFileInfo>
 #include <QFileSystemWatcher>
 #include <QStandardPaths>

@@ -32,11 +34,30 @@ DesktopNotifier::DesktopNotifier(QObject *parent, const QList<QVariant> &)

     connect(watcher, &QFileSystemWatcher::fileChanged, this, &DesktopNotifier::dirty);
     connect(watcher, &QFileSystemWatcher::directoryChanged, this, &DesktopNotifier::dirty);
+
+    // QFileSystemWatcher only reports entries being added or removed, not files being rewritten in place
+    fileWatcher = new KDirWatch(this);
+    fileWatcher->addDir(QStandardPaths::writableLocation(QStandardPaths::DesktopLocation), KDirWatch::WatchFiles);
+    connect(fileWatcher, &KDirWatch::dirty, this, &DesktopNotifier::fileChanged);
 }

 void DesktopNotifier::watchDir(const QString &path)
 {
     watcher->addPath(path);
+    fileWatcher->addDir(path, KDirWatch::WatchFiles);
+}
+
+void DesktopNotifier::fileChanged(const QString &path)
+{
+    if (QFileInfo(path).isDir()) {
+        return;
+    }
+
+    const auto relativePath = QDir(QStandardPaths::writableLocation(QStandardPaths::DesktopLocation)).relativeFilePath(path);
+    QUrl url;
+    url.setScheme(QStringLiteral("desktop"));
+    url.setPath(QDir::cleanPath(u"/" + relativePath));
+    org::kde::KDirNotify::emitFilesChanged(QList{url});
 }

 void DesktopNotifier::dirty(const QString &path)
@@ -82,6 +103,8 @@ void DesktopNotifier::checkDesktopLocation()
     const QUrl &currentLocation = QUrl::fromLocalFile(QStandardPaths::writableLocation(QStandardPaths::DesktopLocation));

     if (m_desktopLocation != currentLocation) {
+        fileWatcher->removeDir(m_desktopLocation.toLocalFile());
+        fileWatcher->addDir(currentLocation.toLocalFile(), KDirWatch::WatchFiles);
         m_desktopLocation = currentLocation;
         org::kde::KDirNotify::emitFilesChanged(QList{QUrl(QStringLiteral("desktop:/"))});
     }
diff --git a/kioworkers/desktop/desktopnotifier.h b/kioworkers/desktop/desktopnotifier.h
index 3640b8e723..7a071acfe3 100644
--- a/kioworkers/desktop/desktopnotifier.h
+++ b/kioworkers/desktop/desktopnotifier.h
@@ -10,6 +10,7 @@
 #include <QUrl>
 #include <kdedmodule.h>

+class KDirWatch;
 class QFileSystemWatcher;

 class DesktopNotifier : public KDEDModule
@@ -25,10 +26,12 @@ public Q_SLOTS:

 private Q_SLOTS:
     void dirty(const QString &path);
+    void fileChanged(const QString &path);

 private:
     void checkDesktopLocation();

     QFileSystemWatcher *watcher;
+    KDirWatch *fileWatcher;
     QUrl m_desktopLocation;
 };
